{
  "schema": "mycounsel.playbook.v1",
  "entries": [
    {
      "id": "DORA-LOCATIONS",
      "category": "STATUTORY_REQUIREMENT",
      "requirement": "Article 30(2)(b): state the regions or countries where the contracted or subcontracted functions and ICT services are provided and where data is processed and stored, and require the provider to notify the customer in advance if it envisages changing them."
    },
    {
      "id": "DORA-ASSISTANCE",
      "category": "STATUTORY_REQUIREMENT",
      "requirement": "Article 30(2)(f): require the provider to assist with ICT incidents related to the contracted ICT service at no additional cost or at a cost determined ex ante."
    },
    {
      "id": "DORA-SLA",
      "category": "STATUTORY_REQUIREMENT",
      "requirement": "Article 30(3)(a): for the assumed critical or important function, require full service level descriptions, including updates and revisions, with precise quantitative and qualitative performance targets that allow effective monitoring and enable appropriate corrective action without undue delay when agreed service levels are not met."
    },
    {
      "id": "DORA-AUDIT",
      "category": "STATUTORY_REQUIREMENT",
      "requirement": "Article 30(3)(e): for the assumed critical or important function, require the right to monitor the provider's performance on an ongoing basis, which entails: (i) unrestricted rights of access, inspection and audit by the customer, or an appointed third party, and by the competent authority, and the right to take copies of relevant documentation on-site if they are critical to the operations of the provider, the effective exercise of which is not impeded or limited by other contractual arrangements or implementation policies; (ii) the right to agree on alternative assurance levels if other clients' rights are affected; (iii) the obligation of the provider to fully cooperate during the onsite inspections and audits performed by the competent authorities, the Lead Overseer, the customer or an appointed third party; and (iv) the obligation to provide details on the scope, procedures to be followed and frequency of such inspections and audits."
    },
    {
      "id": "DORA-RETURN",
      "category": "STATUTORY_REQUIREMENT",
      "requirement": "Article 30(2)(d): ensure access, recovery and return, in an easily accessible format, of personal and non-personal data on the insolvency, resolution or discontinuation of business operations of the provider, or on termination of the contractual arrangements."
    },
    {
      "id": "DORA-EXIT",
      "category": "STATUTORY_REQUIREMENT",
      "requirement": "Article 30(3)(f): for the assumed critical or important function, require exit strategies, in particular a mandatory adequate transition period during which the provider continues providing the services and which allows the customer to migrate to another provider or to in-house solutions consistent with the complexity of the service."
    }
  ]
}
